        QVERIFY(v->browser()->toPlainText().contains(QLatin1String("JeffDeck")));
        QVERIFY(!v->browser()->toPlainText().contains(QLatin1String("publication")));
        // From the ribbon: the tab's topic.
        Ribbon *r = w.ribbon();
        r->showTab(r->tab(QStringLiteral("Transitions")));
